const DATA = {"beginner": [{"group": "Start Here", "lessons": [{"id": "sh", "tag": "Welcome", "title": "Welcome to WIN Tax Academy", "eyebrow": "Start Here", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "WIN Tax Academy · Beginner Tier", "title": "Welcome to the Beginner Track", "sub": "Skills Are Wealth. Build Skills. Create Options.", "tag": "LEARN IT · SEE IT · DO IT · REVIEW IT"}, "script": ["Welcome to WIN Tax Academy. This Beginner track follows one client, Deja Marsh, from her very first W-2 all the way through her first year running her own bakery — so every skill you learn connects to the one before it.", "Same method as always: LEARN IT, SEE IT, DO IT, REVIEW IT. Same shorthand: WATCH, WATCH ME, YOU DO IT, CHECK IT. And the accuracy habit that runs under everything — LOOK at the document, ENTER what it actually says, COMPARE it against what you expect.", "This is skills training. It does not by itself provide an IRS credential, PTIN, professional license, job, or authorization to prepare paid returns. What it gives you is the judgment to know what a return needs, and the discipline to never guess when you don't have it."], "studentDoes": ["Write your WIN Mission — what skill do you want to leave this course able to do?"]}]}, {"group": "Module 1 — Tax Basics & Your Income", "lessons": [{"id": "m1l1", "tag": "Teaching", "title": "How Taxes Actually Work", "eyebrow": "Module 1 · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "WIN Tax Academy · Module 1", "title": "How Taxes Actually Work", "sub": "Marginal ≠ Effective.", "tag": "MEET DEJA MARSH"}, "script": ["Meet Deja Marsh. She's single, works full-time, and this year her W-2 shows $68,200 in wages. Before we touch a single deduction, we need to understand how the tax system actually taxes that income.", "The US uses marginal tax brackets — each bracket only taxes the slice of income that falls inside it, not the whole amount. So Deja doesn't pay one flat rate on all $68,200. She pays a lower rate on the first slice, a higher rate on the next slice, and so on.", "Add up what she paid across every slice, divide by her total income, and that's her effective rate — always lower than her top marginal bracket. That gap between marginal and effective is the whole lesson."]}, {"id": "m1l2", "tag": "Teaching", "title": "Every Income Document & What to Deduct", "eyebrow": "Module 1 · Lesson 2", "flow": ["VIDEO", "DOWNLOAD", "NEXT"], "slide": {"eyebrow": "Income & Deductions", "title": "Every Income Document & What to Deduct", "sub": "No 1099, still taxable.", "tag": "DEDUCTION vs. CREDIT"}, "script": ["Deja only has a W-2 this year, but a real client's income can show up on a dozen different forms — W-2, 1099-NEC, 1099-INT, 1099-DIV, and more. Recognizing the form family is the first skill.", "Here's a rule that surprises a lot of new preparers: income doesn't need a form to be taxable. All income is taxable by default unless the tax code specifically excludes it. ‘Nobody sent me a form for it’ is never a reason to leave it off.", "Once income is sorted, the next skill is telling a deduction from a credit. A deduction reduces the income you're taxed on — its value depends on your bracket. A credit reduces the tax bill itself, dollar for dollar. Most filers take the standard deduction rather than itemizing."], "attachments": ["Income Form Quick Guide", "Deduction & Credit Quick Guide"]}, {"id": "m1l3", "tag": "Practice", "title": "Your Turn: Deja's W-2 Year", "eyebrow": "Module 1 · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn", "title": "Deja's W-2 Year", "sub": "$68,200 wages · $5,100 withheld · $2,000 traditional IRA", "tag": "LOOK → ENTER → COMPARE"}, "image": {"src": "assets/deja_w2.png", "alt": "Mock W-2 — Deja Marsh"}, "script": ["Deja's W-2 shows $68,200 in wages and $5,100 in federal withholding. She also contributed $2,000 to a traditional IRA this year.", "Walk it through: subtract her IRA contribution and standard deduction to find her taxable income, then work through the brackets to find her marginal rate and her tax owed.", "One more check before you close this out: does her IRA contribution make her eligible for the Saver's Credit? Check her income against the limit before answering — due diligence means checking, not assuming."], "studentDoes": ["Calculate Deja's AGI after her $2,000 IRA contribution.", "Calculate her taxable income after the standard deduction.", "Identify her marginal tax bracket.", "Check whether she's eligible for the Saver's Credit.", "Explain your Saver's Credit finding in one sentence."], "quiz": {"label": "Practice check", "questions": [{"q": "Deja's AGI after her $2,000 IRA contribution is:", "opts": ["$68,200", "$66,200", "$70,200"], "answer": 1}, {"q": "Which of these describes how her tax is actually calculated?", "opts": ["She pays her top bracket rate on all of her income", "She pays each bracket's rate only on the income inside it", "She pays one flat rate set by her filing status"], "answer": 1}, {"q": "Deja's IRA contribution is best described as:", "opts": ["A credit", "A deduction", "Not deductible at all"], "answer": 1}, {"q": "Is Deja eligible for the Saver's Credit at her income level?", "opts": ["Yes, she qualifies for the full credit", "No — her AGI is above the eligibility limit", "Only if she is over age 50"], "answer": 1}]}}, {"id": "m1l4", "tag": "WIN Review", "title": "WIN Review: Income In, Deductions Out", "eyebrow": "Module 1 · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Income In, Deductions Out", "sub": "", "tag": "MARGINAL ≠ EFFECTIVE"}, "script": ["Every income document routes somewhere on the return, and income is taxable whether or not a form shows up for it. A deduction shrinks the income you're taxed on; a credit shrinks the tax bill itself, dollar for dollar.", "And the whole tax system runs on marginal brackets — only the slice of income inside each bracket gets that bracket's rate. Effective rate, the real cost, is always lower."], "quiz": {"label": "Module 1 WIN Review — 5 questions", "questions": [{"q": "Deja's effective tax rate compared to her top marginal bracket is:", "opts": ["Higher", "Lower", "The same"], "answer": 1}, {"q": "Income with no 1099 or W-2 attached to it is:", "opts": ["Not taxable", "Taxable unless specifically excluded", "Only taxable over $10,000"], "answer": 1}, {"q": "A $2,000 traditional IRA contribution is an example of:", "opts": ["A credit", "A deduction", "Neither"], "answer": 1}, {"q": "Most filers take:", "opts": ["The standard deduction", "The itemized deduction", "Neither"], "answer": 0}, {"q": "A credit reduces:", "opts": ["The income you're taxed on", "The tax bill itself, dollar for dollar", "Nothing"], "answer": 1}]}}]}, {"group": "Module 2 — Start the Business", "lessons": [{"id": "m2l1", "tag": "Teaching", "title": "Choosing the Right Entity", "eyebrow": "Module 2 · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "WIN Tax Academy · Module 2", "title": "Choosing the Right Entity", "sub": "Sole Prop · LLC · Partnership · S-Corp · C-Corp", "tag": "ONE FORM. ONE TAX TREATMENT."}, "script": ["Deja is ready to turn her weekend baking into Marsh Bakery. Before she sells a single loaf, she has to choose an entity, and that choice decides which form she files and how she's taxed.", "A sole proprietorship and a default single-member LLC both file Schedule C with her personal return — the IRS treats them the same for tax purposes even though the LLC gives her liability protection a sole prop doesn't. A partnership or multi-member LLC files its own return and passes income through on a K-1. An S-corp splits her income into salary and distribution — only the salary gets payroll tax. A C-corp pays its own 21% flat tax, and then she'd be taxed again on any dividends she takes — that's double taxation, and it's rare for a business Deja's size.", "Here's the deduction that makes pass-through status attractive even with self-employment tax on the table: the Qualified Business Income deduction, up to 20% of her qualified business income, straight off her personal return. It phases out at higher income for certain service businesses, but a bakery isn't one of those — so if Marsh Bakery is profitable, this deduction is worth teaching in detail."]}, {"id": "m2l2", "tag": "Teaching", "title": "Getting Set Up & Filing On Time", "eyebrow": "Module 2 · Lesson 2", "flow": ["VIDEO", "DOWNLOAD", "NEXT"], "slide": {"eyebrow": "Setup & Deadlines", "title": "Getting Set Up & Filing On Time", "sub": "EIN → Registration → Bookkeeping Method", "tag": "AN EXTENSION TO FILE IS NOT AN EXTENSION TO PAY"}, "script": ["Before Deja takes her first order, three things need to happen. She needs an EIN — free, straight from IRS.gov — even though a single-member LLC could technically use her Social Security number, an EIN keeps her business paperwork separate from her personal identity. She needs to register with her state, which varies by state but usually means a business registration and a state tax ID. And she needs to pick a bookkeeping method before her first sale, not after her first tax season.", "Once she's set up, the filing calendar depends on her entity. A sole prop or single-member LLC files with her personal 1040 by April 15. A partnership or S-corp files by March 16, with K-1s going out to owners by that same date so they can finish their own returns.", "One rule that trips up a lot of new business owners: an extension to file is not an extension to pay. If Deja thinks she'll owe money, that estimated payment is still due on the original date — filing an extension only buys her more time to finish the paperwork, not more time to pay."], "attachments": ["EIN & Deadline Quick Guide"]}, {"id": "m2l3", "tag": "Practice", "title": "Your Turn: Marsh Bakery Gets an EIN", "eyebrow": "Module 2 · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Marsh Bakery", "title": "Marsh Bakery Gets an EIN", "sub": "Single-Member LLC · Projected First-Year Profit: $58,000", "tag": "WHICH FORM? WHICH DATE?"}, "script": ["Deja registers Marsh Bakery as a single-member LLC and gets her EIN. She projects fifty-eight thousand dollars in net profit for her first year.", "Work through her setup: what form does she file given her entity choice today? What's her filing deadline? And now that you know about the QBI deduction, is her bakery income the kind that qualifies for it, or the kind that phases out at high income?", "She also asks whether she should elect S-corp treatment right away, since a friend told her it saves money. Don't answer that yet — that's next module's lesson. For now, just get her filing basics right."], "studentDoes": ["Identify which form Deja files as a single-member LLC.", "State her filing deadline.", "Confirm whether a bakery's income qualifies for the QBI deduction (not an SSTB).", "Note what you'd need to know before recommending an S-corp election."], "quiz": {"label": "Practice check", "questions": [{"q": "As a default single-member LLC, Deja files:", "opts": ["Form 1065", "Schedule C with her 1040", "Form 1120-S"], "answer": 1}, {"q": "Her filing deadline is:", "opts": ["March 16", "April 15", "December 31"], "answer": 1}, {"q": "Is a bakery a Specified Service Trade or Business (SSTB) subject to QBI phase-out?", "opts": ["Yes", "No"], "answer": 1}]}}, {"id": "m2l4", "tag": "WIN Review", "title": "WIN Review: Entity, QBI & Deadlines", "eyebrow": "Module 2 · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Entity, QBI & Deadlines", "sub": "", "tag": "FILE ON TIME EVEN IF YOU CAN'T PAY"}, "script": ["Entity choice decides the form, the tax treatment, and whether self-employment tax applies to all of it or just part of it. A sole prop and a default LLC are taxed the same way; an S-corp splits salary from distribution; a C-corp is taxed twice.", "The QBI deduction can shelter up to 20% of qualified business income for a pass-through owner — a real reason to stay pass-through even with self-employment tax in the picture.", "And no matter the entity: an extension to file buys time on the paperwork, never on the payment."], "quiz": {"label": "Module 2 WIN Review — 5 questions", "questions": [{"q": "A sole prop and a default single-member LLC are taxed:", "opts": ["Completely differently", "The same way for federal tax purposes", "Only the LLC pays tax"], "answer": 1}, {"q": "The QBI deduction can shelter up to:", "opts": ["10%", "20%", "50% of qualified business income"], "answer": 1}, {"q": "An S-corp's salary portion is subject to:", "opts": ["No tax", "Payroll tax (FICA)", "Self-employment tax"], "answer": 1}, {"q": "An extension to file:", "opts": ["Also extends the payment deadline", "Does not extend the payment deadline", "Cancels the deadline entirely"], "answer": 1}, {"q": "A C-corp's profits are taxed:", "opts": ["Once, at the owner level only", "Once, at the corporate level only", "Twice — corporate level, then again on dividends"], "answer": 2}]}}]}, {"group": "Module 3 — Money, Payroll & The Books", "lessons": [{"id": "m3l1", "tag": "Teaching", "title": "Self-Employment Tax & Quarterly Estimates", "eyebrow": "Module 3 · Lesson 1", "flow": ["VIDEO", "DOWNLOAD", "NEXT"], "slide": {"eyebrow": "WIN Tax Academy · Module 3", "title": "Self-Employment Tax", "sub": "15.3% — Social Security + Medicare, both halves", "tag": "QUARTERLY ESTIMATES: APR • JUN • SEP • JAN"}, "script": ["As a W-2 employee, Deja's employer paid half her Social Security and Medicare tax and withheld the other half from her paycheck. As a business owner, she IS the employer and the employee — she owes both halves herself. That's self-employment tax: 15.3% of her net earnings from self-employment. The good news: she gets to deduct half of that SE tax on her personal return, since that half is the ‘employer’ portion.", "Because no one is withholding tax from her bakery income the way her old employer withheld from her paycheck, Deja has to pay as she goes: quarterly estimated payments, due mid-April, mid-June, mid-September, and mid-January. Miss a quarter, or pay too little, and she can owe an underpayment penalty even if she pays everything by April 15 of the following year.", "On top of SE tax, her net profit is also subject to regular income tax. Both apply to the same net profit — that surprises a lot of new business owners, and it's exactly why quarterly estimates matter."], "attachments": ["SE Tax & Estimated Payment Quick Guide"]}, {"id": "m3l2", "tag": "Teaching", "title": "Payroll & Bookkeeping Basics", "eyebrow": "Module 3 · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Payroll & Books", "title": "Payroll & Bookkeeping Basics", "sub": "Employee vs. Independent Contractor", "tag": "CASH vs. ACCRUAL — PICK ONE, STAY CONSISTENT"}, "script": ["Marsh Bakery is growing, and Deja wants to bring on help. The first question: is that person an employee or an independent contractor? The test looks at behavioral control — does Deja control how the work gets done — financial control — who provides the tools, who bears the profit or loss risk — and the relationship itself — is there a contract, benefits, an ongoing relationship. Get this wrong and misclassify an employee as a contractor, and Deja can owe back payroll taxes and penalties.", "If she hires an employee, she withholds federal and state income tax plus the employee's half of FICA, matches the employer's half of FICA herself, and pays federal and state unemployment tax. If she works with a contractor instead, she pays the invoiced amount, gets a W-9 up front, and issues a 1099-NEC if she pays that contractor $600 or more for the year — no withholding either way.", "And every business needs a bookkeeping method. Cash basis records income when she receives it and expenses when she pays them — simple, and what most small businesses use. Accrual basis records income when earned and expenses when incurred, regardless of when cash moves — required for certain larger businesses. Whichever Deja picks, she needs to pick it early and stay consistent."]}, {"id": "m3l3", "tag": "Practice", "title": "Your Turn: Run Marsh Bakery's First Quarter", "eyebrow": "Module 3 · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Marsh Bakery, Q1", "title": "Run Marsh Bakery's First Quarter", "sub": "Gross Receipts: $14,500 · New Hire: Part-Time Baker", "tag": "EMPLOYEE OR CONTRACTOR? WHAT'S OWED?"}, "script": ["Marsh Bakery closes its first quarter with fourteen thousand five hundred dollars in gross receipts. Deja also brings on a part-time baker — the baker uses Deja's kitchen, Deja sets the hours and the recipes, and the arrangement is ongoing with no separate contract.", "First: is the baker an employee or an independent contractor, based on those facts? Second: given her Q1 gross receipts, does Deja need to make an estimated payment this quarter, and by what date? Third: what taxes apply to her net profit — just income tax, or income tax plus something else?"], "studentDoes": ["Apply the three-factor test to the baker's working arrangement.", "Classify the baker as employee or contractor.", "Identify Deja's Q1 estimated payment due date.", "Name both taxes that apply to her net profit.", "State what form Deja would issue the baker if contractor status were supported instead."], "quiz": {"label": "Practice check", "questions": [{"q": "Based on the facts given, the baker is best classified as:", "opts": ["An independent contractor", "An employee"], "answer": 1}, {"q": "Deja's Q1 estimated payment is due:", "opts": ["April 15", "June 15", "September 15"], "answer": 0}, {"q": "Her net profit is subject to:", "opts": ["Income tax only", "Income tax and self-employment tax"], "answer": 1}, {"q": "Half of her self-employment tax is:", "opts": ["Not deductible", "Deductible on her personal return"], "answer": 1}]}}, {"id": "m3l4", "tag": "WIN Review", "title": "WIN Review: SE Tax, Payroll & the Books", "eyebrow": "Module 3 · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "SE Tax, Payroll & the Books", "sub": "", "tag": "PICK A METHOD. STAY CONSISTENT."}, "script": ["Self-employment tax covers both the employee and employer halves of Social Security and Medicare — 15.3% of net self-employment earnings, with half deductible. It stacks on top of regular income tax on the same profit, which is why quarterly estimated payments matter.", "Worker classification comes down to three factors: behavioral control, financial control, and the relationship itself. Get it wrong and the business — not the worker — can owe the back taxes.", "And bookkeeping method is a choice made once and kept: cash basis for most small businesses, accrual when the business or its size requires it."], "quiz": {"label": "Module 3 WIN Review — 5 questions", "questions": [{"q": "Self-employment tax equals:", "opts": ["7.65%", "15.3%", "21%"], "answer": 1}, {"q": "The three-factor worker classification test looks at:", "opts": ["Pay rate, hours, location", "Behavioral control, financial control, relationship", "Age, experience, references"], "answer": 1}, {"q": "A contractor paid $600 or more in a year should receive a:", "opts": ["W-2", "1099-NEC", "W-4"], "answer": 1}, {"q": "Cash basis bookkeeping records income when:", "opts": ["It is earned, regardless of payment", "It is received", "The client is invoiced"], "answer": 1}, {"q": "Missing a quarterly estimated payment can result in:", "opts": ["No consequence if paid by April 15", "An automatic audit", "An underpayment penalty"], "answer": 2}]}}]}, {"group": "Module 4 — Records, Deductions & Staying Compliant", "lessons": [{"id": "m4l1", "tag": "Teaching", "title": "Recordkeeping & Retention", "eyebrow": "Module 4 · Lesson 1", "flow": ["VIDEO", "DOWNLOAD", "NEXT"], "slide": {"eyebrow": "WIN Tax Academy · Module 4", "title": "Recordkeeping & Retention", "sub": "Keep records 3 years — 7 if you file a loss", "tag": "NO RECEIPT, NO DEDUCTION"}, "script": ["Deja's bakery generates receipts, invoices, mileage logs, and bank statements all year. The general rule: keep tax records for three years from the filing date, since that's the standard IRS audit window. But if she ever claims a loss from worthless securities or a bad debt deduction, that window stretches to seven years — and if she ever fails to report income she should have reported, or files no return at all, there's no time limit at all.", "The habit that protects Deja more than any single rule: no receipt, no deduction. A bank statement showing a charge isn't proof of a business purpose — she needs the receipt, the invoice, or the log entry that shows what it was for and why it was business."], "attachments": ["Recordkeeping Retention Quick Guide"]}, {"id": "m4l2", "tag": "Teaching", "title": "Deductions, Depreciation & Deadlines", "eyebrow": "Module 4 · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Deductions & Deadlines", "title": "Deductions, Depreciation & Deadlines", "sub": "Ordinary and necessary", "tag": "HOME OFFICE: REGULAR AND EXCLUSIVE USE"}, "script": ["A business deduction has to be ordinary — common in Deja's type of business — and necessary — helpful and appropriate for it. A large equipment purchase, like a commercial oven, isn't fully deducted the year she buys it in every case; depreciation spreads that cost over the equipment's useful life, though certain elections can allow faster write-offs.", "The home office deduction is one of the most misused, and one of the strictest: the space has to be used regularly AND exclusively for business. A corner of the kitchen table that the kids also use for homework does not qualify, no matter how many hours of bakery work happen there — exclusive means exclusive.", "And every deduction lives inside a deadline. Missing a filing deadline can mean a failure-to-file penalty; missing a payment deadline, even with an extension on file, can mean a failure-to-pay penalty and interest on top."]}, {"id": "m4l3", "tag": "Capstone", "title": "Your Turn: Deja Capstone", "eyebrow": "Module 4 · Lesson 3", "flow": ["VIDEO", "CAPSTONE", "NEXT"], "slide": {"eyebrow": "Your Turn — Deja Capstone", "title": "Deja Capstone", "sub": "Year-End Gross Receipts: $58,400", "tag": "SEPARATE WHAT'S SUPPORTED FROM WHAT ISN'T"}, "table": {"title": "Deja's Year-End Documents", "headers": ["Item", "Detail"], "rows": [["Commercial oven", "$3,100, bought on personal credit card"], ["Home office", "150 sq ft, also used by her kids for homework"], ["Baker payment", "$2,800 paid in cash, no W-9 on file"]]}, "script": ["Marsh Bakery closes its first full year with fifty-eight thousand four hundred dollars in gross receipts. Deja brings you a mix of documentation to sort through.", "Supported and clear: a three thousand one hundred dollar commercial oven, bought on her personal credit card but used entirely for the bakery — personal card doesn't disqualify a business expense, but she needs the receipt. Not supported as claimed: a 150-square-foot room she calls her home office, which her kids also use most evenings for homework — that fails the exclusive-use test as described. Incomplete: two thousand eight hundred dollars paid in cash to her part-time baker, with no W-9 on file and no 1099 issued.", "Your job is the same one a preparer does every season: sort what's supported, flag what's incomplete, and identify exactly what additional information or documentation is needed before anything gets claimed or reported — never fill the gap with a guess."], "studentDoes": ["Confirm the oven purchase qualifies as a business deduction despite being on a personal card.", "Apply the exclusive-use test to the home office claim and determine whether it qualifies.", "Identify what's missing for the cash-paid baker (W-9, possible 1099-NEC).", "Separate the three items into supported, unsupported, and incomplete.", "Write the follow-up questions you would ask Deja before finalizing her return."], "quiz": {"label": "Capstone — 5-question quiz", "questions": [{"q": "The $3,100 oven, though bought on a personal card, is:", "opts": ["Disqualified because of the card used", "An eligible business expense with proper documentation"], "answer": 1}, {"q": "The home office claim fails because:", "opts": ["The room is too small", "It is not used exclusively for business", "She doesn't own her home"], "answer": 1}, {"q": "Before claiming a deduction for paying the baker $2,800 in cash, Deja needs:", "opts": ["Nothing further, cash is always deductible", "A W-9 on file and to determine if a 1099-NEC is required", "A separate business bank account"], "answer": 1}, {"q": "The correct treatment of the home office claim, as described, is to:", "opts": ["Claim it in full", "Do not claim it as described; the exclusive-use test is not met", "Claim half of it"], "answer": 1}, {"q": "The core recordkeeping standard behind every deduction is:", "opts": ["A bank statement is enough", "No receipt, no deduction", "Estimates are acceptable if reasonable"], "answer": 1}]}}, {"id": "m4l4", "tag": "Final", "title": "WIN Review + Final Assessment", "eyebrow": "Module 4 · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review — Final Assessment", "title": "Records, Deductions & Compliance", "sub": "", "tag": "WHEN IN DOUBT, ASK — DON'T GUESS"}, "script": ["Deja Marsh started this course as a W-2 employee reading her own paystub for the first time. She's finishing it as a business owner who understands her entity, her deductions, her payroll obligations, and her recordkeeping duties — and knows exactly when to stop and ask a real preparer instead of guessing.", "That's the whole course in one habit: LOOK at the document. ENTER what it actually says. COMPARE it against what you expect. And when something doesn't add up or isn't fully documented, stop and ask rather than filling the gap yourself."], "quiz": {"label": "Final Assessment — 6 questions", "questions": [{"q": "Standard tax record retention is:", "opts": ["1 year", "3 years", "10 years"], "answer": 1}, {"q": "A business deduction must be:", "opts": ["Convenient", "Ordinary and necessary", "Pre-approved by the IRS"], "answer": 1}, {"q": "The home office deduction requires:", "opts": ["Regular use only", "Regular AND exclusive use", "Any home workspace"], "answer": 1}, {"q": "An extension to file:", "opts": ["Extends the payment deadline too", "Does not extend the payment deadline", "Is only for businesses"], "answer": 1}, {"q": "Self-employment tax covers:", "opts": ["Income tax only", "Both employer and employee halves of Social Security and Medicare", "State tax only"], "answer": 1}, {"q": "When documentation is incomplete, the correct step is to:", "opts": ["Estimate a reasonable number", "Ask the client and gather what's missing before finalizing", "Leave it off the return entirely without asking"], "answer": 1}]}}]}], "advanced": [{"group": "Start Here", "lessons": [{"id": "sh", "tag": "Welcome", "title": "Welcome to the Advanced Track", "eyebrow": "Start Here", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "WIN Tax & Bookkeeping Academy", "title": "Welcome to the Advanced Track", "sub": "Three Tracks. Ten Modules. One Habit: LOOK → ENTER → COMPARE.", "tag": "SKILLS ARE WEALTH."}, "script": ["Welcome back. If you finished WIN Tax Academy, you already know how to read a W-2, sort income, and check accuracy the WIN way — LOOK at the document, ENTER what it actually says, COMPARE it against what you expect. This Advanced track takes that same habit and points it at three new challenges.", "Track 1, Individual Tax Foundations, goes deeper on the individual return — how the tax system actually works, every income document you'll see, and the deductions and credits that matter. You'll work with Marcus Webb, a W-2 employee with investment income who thinks he qualifies for a credit he doesn't.", "Track 2, Small Business Formation & Filing, is about the moment someone stops being an employee and starts being a business owner. You'll work with Priya Shah, a freelance graphic designer deciding whether an S-corp election actually saves her money — and by how much.", "Track 3, Bookkeeping, Recordkeeping & Compliance, is where the books get built and the deadlines get real. You'll work with Terrence Cole, who runs a mobile pet-grooming business and needs his chart of accounts and his deductions sorted correctly. And you'll close the course with Angela Ruiz's capstone — a messier file, on purpose, where nothing gets finalized until it's fully supported.", "One more time, before we start — this is skills training. It doesn't by itself hand you an IRS credential, a PTIN, a professional license, a job, or authorization to prepare paid returns. What it gives you is the judgment to know what a return needs, and the discipline to never guess when you don't have it."], "studentDoes": ["Write your WIN Mission for the Advanced track — what skill do you want to leave this course able to do that you couldn't do before?"]}]}, {"group": "Track 1 · Module A — How Taxes Actually Work", "lessons": [{"id": "a1", "tag": "Teaching", "title": "The Progressive System", "eyebrow": "Module A · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "WIN Tax & Bookkeeping Academy · Module A", "title": "The Progressive System", "sub": "Marginal ≠ Effective", "tag": "2025 BRACKETS, FILED 2026"}, "script": ["“I'm in the 24% bracket, so I pay 24% on everything I make.” That's the single most common tax myth out there, and it's wrong — and once you can explain why, you've explained the whole progressive system.", "The US uses marginal tax brackets. Each bracket only taxes the income that falls inside it, not your whole income. So if you're single and your taxable income is $85,000, you don't pay one flat rate on all $85,000. You pay 10% on the first slice, 12% on the next slice, 22% on the slice after that, and so on — only the top slice actually hits your “bracket” rate. Add up what you paid across every slice, divide by total income, and that's your effective rate — always lower than your marginal bracket.", "Watch this on screen: at $85,000 single, the marginal bracket is 22%, but the effective rate — what she actually pays as a percentage of total income — works out closer to 15%. That gap is the entire lesson."]}, {"id": "a2", "tag": "Teaching", "title": "Who Has to File & the Pay-As-You-Go Rule", "eyebrow": "Module A · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Filing & Withholding", "title": "Who Has to File", "sub": "2025 thresholds by status & age", "tag": "PAY-AS-YOU-GO: WITHHOLDING OR ESTIMATES"}, "script": ["Not everyone has to file, but the thresholds are lower than most people think, and they change based on filing status and age. Below the threshold, filing is optional — often still worth it to get a refund of withholding. Above it, filing is required regardless of whether you'd owe anything.", "One threshold catches people by surprise: self-employment income. Earn $400 or more net from self-employment, and you must file — that rule doesn't care what the general filing threshold is for your status.", "And here's the pay-as-you-go principle behind the whole system: the IRS expects tax paid throughout the year, not in one lump sum in April. For a W-2 employee, that's withholding. For a business owner or someone with other untaxed income, that's estimated payments."], "studentDoes": ["Match each of four mini-profiles (a retired single filer with $8,000 in Social Security only; a single filer with $15,000 in W-2 wages; a self-employed dog walker who nets $650; a married couple filing jointly with $30,000 in combined wages) to “must file” or “filing optional.”"]}, {"id": "a3", "tag": "Practice", "title": "Your Turn: Marcus — Bracket & Filing Check", "eyebrow": "Module A · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Marcus Webb", "title": "Bracket & Filing Check", "sub": "Single · W-2 Wages: $91,400", "tag": "MARGINAL? EFFECTIVE? MUST HE FILE?"}, "image": {"src": "assets/marcus_docs.png", "alt": "Document Set — Marcus Webb"}, "script": ["Marcus Webb is single with $91,400 in W-2 wages this year. Before touching his deductions or credits, get the fundamentals right: what's his marginal bracket, what's his effective rate once you work through every slice, and does he even have to file — obviously yes, but walk through why, not just the answer.", "Use LOOK → ENTER → COMPARE: look at his W-2 wages, enter them into the bracket structure slice by slice, then compare his effective rate against his marginal bracket so you can explain the gap to him in plain language."], "studentDoes": ["Identify Marcus's marginal tax bracket at $91,400 single.", "Calculate his tax slice by slice through each bracket.", "Calculate his effective rate (total tax ÷ total income).", "Confirm he must file and explain why the filing threshold applies to him.", "Write one sentence you'd say to Marcus explaining why his effective rate is lower than his bracket."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "a4", "tag": "WIN Review", "title": "WIN Review: The Progressive System", "eyebrow": "Module A · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "The Progressive System", "sub": "", "tag": "FILE BASED ON STATUS, AGE & INCOME TYPE"}, "script": ["Marginal brackets only tax the income inside each slice — never your whole income at one rate. Effective rate is your real cost, always lower than your top marginal bracket. And filing requirements depend on filing status, age, and income type — with self-employment income tripping the $400 threshold regardless of anything else."], "quiz": {"label": "Module A WIN Review — 5 questions", "questions": [{"q": "A taxpayer in the 24% bracket pays 24% tax on:", "opts": ["Their entire income", "Only the income that falls in the 24% slice", "Nothing, brackets are just labels"], "answer": 1}, {"q": "Effective tax rate is always:", "opts": ["Higher than the marginal bracket", "Equal to the marginal bracket", "Lower than the marginal bracket"], "answer": 2}, {"q": "Self-employment income requires filing once net earnings reach:", "opts": ["$400", "$1,000", "$12,000"], "answer": 0}, {"q": "The “pay-as-you-go” principle is satisfied for a W-2 employee through:", "opts": ["Estimated payments", "Withholding", "A single April payment"], "answer": 1}, {"q": "Filing requirements depend on:", "opts": ["Filing status, age, and income type", "Only total income", "Only filing status"], "answer": 0}]}}]}, {"group": "Track 1 · Module B — Every Income Document", "lessons": [{"id": "b1", "tag": "Teaching", "title": "The Income Form Family", "eyebrow": "Module B · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Income Forms", "title": "The Income Form Family", "sub": "W-2 • 1099-NEC • 1099-MISC • 1099-K • 1099-INT/DIV/B/R/G • SSA-1099 • K-1", "tag": "2025–26 THRESHOLDS"}, "script": ["By now you know the W-2 cold. This lesson builds out the rest of the family, because a preparer who only recognizes a W-2 turns away half a real client's documents.", "1099-NEC reports nonemployee compensation — issued once a business pays a contractor $600 or more. 1099-MISC catches other payment types like rent or prizes. 1099-K reports payment-app and card processing activity. 1099-INT and 1099-DIV report interest and dividends from banks and brokerages. 1099-B reports investment sales. 1099-R reports retirement plan and pension distributions. 1099-G reports government payments like unemployment. SSA-1099 reports Social Security benefits. And a Schedule K-1 reports a taxpayer's share of income from a partnership, S-corp, estate, or trust.", "Every one of these forms exists so the IRS gets a copy of the same information the taxpayer does — which is exactly why a form that doesn't get entered is a mismatch waiting to happen."]}, {"id": "b2", "tag": "Teaching", "title": "The Income That Isn't on a Form", "eyebrow": "Module B · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Unreported Income", "title": "The Income That Isn't on a Form", "sub": "No 1099, still taxable", "tag": "SOCIAL SECURITY: 0% / 50% / 85% TAXABLE"}, "script": ["Here's a rule that surprises new preparers as much as it surprises clients: income doesn't need a form to be taxable. The default is that all income is taxable unless the tax code specifically excludes it. Gambling winnings, jury duty pay, canceled debt reported on a 1099-C, digital asset transactions — all taxable, form or no form.", "Social Security benefits get their own formula. Depending on a taxpayer's “combined income” — adjusted gross income, plus nontaxable interest, plus half their Social Security benefits — anywhere from 0% to 85% of those benefits become taxable. It's never all of it, but it's often more than people expect."]}, {"id": "b3", "tag": "Practice", "title": "Your Turn: Marcus — Investment & Retirement Income", "eyebrow": "Module B · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Marcus Webb", "title": "Investment & Retirement Income", "sub": "1099-DIV: $640 · 1099-INT: $85 · IRA Distribution: $4,200", "tag": "SORT IT. FLAG WHAT NEEDS A SECOND LOOK."}, "image": {"src": "assets/marcus_docs.png", "alt": "Document Set — Marcus Webb"}, "script": ["Marcus brings you three more documents this year: a 1099-DIV showing $640 in qualified dividends, a 1099-INT showing $85 in interest, and a $4,200 distribution from his traditional IRA.", "Sort each one by type and tax treatment. Qualified dividends get preferential capital-gains rates rather than ordinary rates. Interest is ordinary income, full stop. And the IRA distribution needs a second look: is he under 59½? If so, this might trigger an early-withdrawal penalty on top of ordinary income tax — that's exactly the kind of thing you ask the client about rather than assume."], "studentDoes": ["Classify the 1099-DIV amount and note its tax treatment (qualified vs. ordinary).", "Classify the 1099-INT amount and note its tax treatment.", "Classify the IRA distribution and flag the follow-up question needed (age, for penalty purposes).", "Identify whether Social Security combined-income rules apply to Marcus this year (they don't — he has no Social Security income)."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "b4", "tag": "WIN Review", "title": "WIN Review: Income Documents", "eyebrow": "Module B · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Income Documents", "sub": "", "tag": "SOCIAL SECURITY: NEVER MORE THAN 85% TAXABLE"}, "script": ["Every income form routes to a specific line on the return, and recognizing the form is the first step to entering it correctly. But the form isn't the trigger for taxability — income is taxable by default, form or no form. And Social Security has its own sliding scale, from 0% up to a cap of 85%, never the whole benefit."], "quiz": {"label": "Module B WIN Review — 5 questions", "questions": [{"q": "A 1099-NEC is issued once a contractor is paid:", "opts": ["$400 or more", "$600 or more", "$1,000 or more"], "answer": 1}, {"q": "Income with no 1099 or W-2 attached to it is:", "opts": ["Not taxable", "Taxable unless specifically excluded", "Only taxable if over $10,000"], "answer": 1}, {"q": "The maximum percentage of Social Security benefits that can be taxable is:", "opts": ["50%", "85%", "100%"], "answer": 1}, {"q": "A Schedule K-1 reports a taxpayer's share of income from:", "opts": ["A W-2 employer", "A partnership, S-corp, estate, or trust", "A bank account"], "answer": 1}, {"q": "Qualified dividends are generally taxed:", "opts": ["At ordinary income rates", "At preferential capital-gains rates", "Not at all"], "answer": 1}]}}]}, {"group": "Track 1 · Module C — Deductions & Credits That Matter", "lessons": [{"id": "c1", "tag": "Teaching", "title": "Deduction vs. Credit", "eyebrow": "Module C · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Deductions & Credits", "title": "Deduction vs. Credit", "sub": "A deduction shrinks the income you're taxed on", "tag": "A CREDIT SHRINKS THE TAX ITSELF"}, "script": ["Before touching a single number, separate these two ideas. A deduction reduces the income you're taxed on — its value depends on your marginal rate, so a $1,000 deduction saves someone in the 22% bracket $220, and saves someone in the 12% bracket only $120. A credit reduces the tax bill itself, dollar for dollar — a $1,000 credit is worth exactly $1,000 to everyone who qualifies, regardless of bracket.", "Credits split further into refundable and nonrefundable. A nonrefundable credit can only reduce your tax to zero — any leftover credit disappears. A refundable credit can push you below zero and generate an actual refund beyond what you paid in."]}, {"id": "c2", "tag": "Teaching", "title": "Standard vs. Itemized + Common Credits", "eyebrow": "Module C · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Standard vs. Itemized", "title": "Common Credits", "sub": "Most filers take the standard deduction", "tag": "CHILD TAX CREDIT • EITC • AOTC • LIFETIME LEARNING CREDIT"}, "script": ["Every filer chooses the larger of two paths: the standard deduction, a flat amount set by filing status, or itemizing — adding up specific expenses like mortgage interest, state and local taxes (capped), and charitable giving. Since the standard deduction roughly doubled several years back, the large majority of filers come out ahead taking it.", "Then come the credits that show up again and again: the Child Tax Credit, per qualifying child under the income phase-out; the Earned Income Tax Credit, a refundable credit for lower- and moderate-income workers that scales with earned income and number of qualifying children; the American Opportunity Tax Credit and Lifetime Learning Credit, both for education expenses."]}, {"id": "c3", "tag": "Practice", "title": "Your Turn: Marcus — Credit Eligibility Check", "eyebrow": "Module C · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Marcus Webb", "title": "Credit Eligibility Check", "sub": "He's Asking About the EITC", "tag": "CHECK ELIGIBILITY BEFORE YOU ANSWER"}, "image": {"src": "assets/marcus_docs.png", "alt": "Document Set — Marcus Webb"}, "script": ["Marcus heard about the Earned Income Tax Credit from a coworker and wants to know if he qualifies. Don't just answer — walk the eligibility test the way a real preparer would.", "The EITC has income limits that vary based on number of qualifying children, and Marcus has no children. The limit for a filer with no qualifying children is much lower than his $91,400 in wages — he's well above it. So the answer is no, and you tell him plainly why.", "But don't stop at “no.” Marcus took a $4,200 IRA distribution this year — remind yourself of the Saver's Credit from earlier in the course, and check whether his income is low enough to qualify. At $91,400 single, he's actually above the Saver's Credit limit too. The real lesson here isn't finding him a credit; it's confirming, correctly, that he doesn't currently qualify for either one."], "studentDoes": ["Check Marcus against EITC eligibility (income limit + qualifying children) and state the result.", "Explain in plain language why he doesn't qualify.", "Check Marcus against Saver's Credit income limits and state the result.", "Write what you'd tell Marcus about why neither credit applies to him this year."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "c4", "tag": "Final", "title": "WIN Review: Deductions & Credits (Closes Track 1)", "eyebrow": "Module C · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review — Closes Track 1", "title": "Deductions & Credits", "sub": "", "tag": "CHECK ELIGIBILITY — DON'T ASSUME IT"}, "script": ["A deduction's value depends on your bracket; a credit is worth its full dollar amount to anyone who qualifies. Most filers take the standard deduction rather than itemizing. And credits like the EITC, Child Tax Credit, and education credits all carry real eligibility rules — checking them correctly, including confirming when someone does NOT qualify, is exactly the skill Marcus's lesson tested.", "That closes Track 1, Individual Tax Foundations. Next up: Track 2, where Priya Shah turns freelance work into a real business."], "quiz": {"label": "Module C WIN Review — 5 questions", "questions": [{"q": "A deduction's value to the taxpayer depends on:", "opts": ["Their marginal tax bracket", "A flat dollar amount for everyone", "Nothing, all deductions are worth the same"], "answer": 0}, {"q": "A refundable credit can:", "opts": ["Only reduce tax to zero", "Generate a refund beyond taxes paid in", "Never be claimed by lower-income filers"], "answer": 1}, {"q": "Most filers take:", "opts": ["The itemized deduction", "The standard deduction", "Neither"], "answer": 1}, {"q": "The EITC is:", "opts": ["Nonrefundable", "Refundable", "Only for business owners"], "answer": 1}, {"q": "Marcus does not qualify for the EITC primarily because:", "opts": ["He has too many qualifying children", "His income is too high and he has no qualifying children", "He is self-employed"], "answer": 1}]}}]}, {"group": "Track 2 · Module D — Choosing the Right Entity", "lessons": [{"id": "d1", "tag": "Teaching", "title": "Entity Types & Tax Treatment", "eyebrow": "Module D · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Track 2 · Module D", "title": "Entity Types & Tax Treatment", "sub": "Sole Prop • LLC • Partnership • S-Corp • C-Corp", "tag": "ONE CHOICE DECIDES THE FORM, THE TAX, AND THE SE-TAX EXPOSURE"}, "script": ["Welcome to Track 2. This track follows Priya Shah, a freelance graphic designer, as she turns a side hustle into a real business — and every module follows one decision she has to make.", "A sole proprietorship and a default single-member LLC are taxed identically — both file Schedule C with the owner's 1040, and both expose 100% of net profit to self-employment tax. A multi-member LLC or partnership files its own informational return, Form 1065, and passes income through to each owner on a Schedule K-1. An S-corp splits owner income into salary, subject to payroll tax, and distribution, which isn't. A C-corp is taxed at the entity level, currently a flat 21%, and then taxed again when profits are distributed as dividends."]}, {"id": "d2", "tag": "Teaching", "title": "The QBI Deduction", "eyebrow": "Module D · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "QBI Deduction", "title": "The QBI Deduction", "sub": "Up to 20% of qualified business income", "tag": "SSTB PHASE-OUTS • REASONABLE COMPENSATION ISN'T QBI"}, "script": ["The Qualified Business Income deduction is a major reason pass-through status stays attractive even with self-employment tax in the picture: up to 20% of qualified business income, deducted straight on the owner's personal return.", "But it has limits. Specified Service Trades or Businesses — law, health, consulting, and similar service fields — phase this deduction out at higher income levels. Is graphic design an SSTB? Generally no — it's a creative/production service, not one of the listed SSTB categories.", "One more wrinkle: if an S-corp owner takes a salary, that salary is treated as wages for QBI purposes — it does NOT count as qualified business income. Only the distribution portion counts toward the 20% QBI calculation."]}, {"id": "d3", "tag": "Practice", "title": "Your Turn: Priya — Entity Choice", "eyebrow": "Module D · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Priya Shah", "title": "Entity Choice", "sub": "Sole Proprietor · Net Profit: $92,000", "tag": "STAY SOLE PROP, OR ELECT S-CORP?"}, "image": {"src": "assets/priya_docs.png", "alt": "Document Set — Priya Shah"}, "script": ["Priya nets $92,000 this year as a sole proprietor. A friend told her S-corp status “saves thousands in taxes,” and she wants to know if that's true for her.", "As a sole prop, all $92,000 is subject to self-employment tax. If she elects S-corp status and sets a reasonable salary of $55,000, only that $55,000 is subject to payroll tax; the remaining $37,000 comes out as a distribution, subject to income tax but NOT payroll or self-employment tax.", "Work through the SE-tax exposure both ways so you can show Priya the actual dollar difference. Then flag the other side of the ledger: an S-corp means payroll processing and real cost and complexity. And flag the biggest risk: if the IRS decides $55,000 wasn't a “reasonable” salary for the work Priya does, that draws scrutiny."], "studentDoes": ["Calculate Priya's SE-tax exposure as a sole proprietor on the full $92,000.", "Calculate her payroll-tax exposure as an S-corp on a $55,000 salary only.", "State the dollar difference in tax exposure between the two structures.", "Name at least two non-tax factors (cost, complexity, liability) that also matter to the decision.", "Explain the “reasonable compensation” risk in your own words."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "d4", "tag": "WIN Review", "title": "WIN Review: Entity & QBI", "eyebrow": "Module D · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Entity & QBI", "sub": "", "tag": "SALARY IS NOT QBI — ONLY DISTRIBUTIONS ARE"}, "script": ["Entity choice is never just a filing decision — it decides the form filed, how income is taxed, and how much of it is exposed to self-employment or payroll tax. The QBI deduction can shelter up to 20% of qualified business income for a pass-through owner, with service businesses like law and consulting facing phase-outs that a business like Priya's graphic design work doesn't."], "quiz": {"label": "Module D WIN Review — 5 questions", "questions": [{"q": "A sole proprietorship and a default single-member LLC are taxed:", "opts": ["Completely differently", "The same way for federal tax purposes"], "answer": 1}, {"q": "The QBI deduction can shelter up to:", "opts": ["10%", "20%", "50% of qualified business income"], "answer": 1}, {"q": "Graphic design is generally treated as:", "opts": ["An SSTB subject to phase-out", "Not an SSTB"], "answer": 1}, {"q": "In an S-corp, which portion of owner income is subject to payroll tax?", "opts": ["The salary only", "The distribution only", "Both equally"], "answer": 0}, {"q": "For QBI purposes, an S-corp owner's reasonable salary is treated as:", "opts": ["Qualified business income", "Wages, not QBI"], "answer": 1}]}}]}, {"group": "Track 2 · Module E — Getting Set Up & Filing On Time", "lessons": [{"id": "e1", "tag": "Teaching", "title": "EIN, Registration & Recordkeeping Setup", "eyebrow": "Module E · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Getting Set Up", "title": "EIN, Registration & Setup", "sub": "EIN → State Registration → Bookkeeping Method", "tag": "DO THIS BEFORE THE FIRST INVOICE, NOT AFTER"}, "script": ["Priya has decided: she's electing S-corp treatment. Before that election means anything on paper, three setup steps come first. An EIN, free from IRS.gov — required for an S-corp regardless of size, since she'll be running payroll. State and local registration. And a bookkeeping method chosen now, not scrambled together at tax time."]}, {"id": "e2", "tag": "Teaching", "title": "Forms & Deadlines by Entity", "eyebrow": "Module E · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Forms & Deadlines", "title": "Forms & Deadlines by Entity", "sub": "Schedule C • 1065 + K-1 • 1120-S + K-1 • 1120", "tag": "AN EXTENSION TO FILE IS NOT AN EXTENSION TO PAY"}, "script": ["Every entity has its own form and its own calendar. A sole prop files Schedule C with the personal 1040, due April 15. A partnership files Form 1065, issuing K-1s to each partner, due March 16. An S-corp files Form 1120-S, also issuing K-1s, also due March 16. A C-corp files Form 1120, generally due April 15.", "Every one of these has an extension option — Form 7004 for business returns — but the rule never changes: an extension buys time on the paperwork, never on the payment."]}, {"id": "e3", "tag": "Practice", "title": "Your Turn: Priya — Build the Filing Calendar", "eyebrow": "Module E · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Priya Shah", "title": "Build the Filing Calendar", "sub": "Now Taxed as an S-Corp", "tag": "BUILD HER FULL-YEAR CALENDAR"}, "image": {"src": "assets/priya_docs.png", "alt": "Document Set — Priya Shah"}, "script": ["Priya's S-corp election is in place. Build her complete filing calendar for the year: when does her 1120-S need to be filed, when do her K-1s need to reach her, when is her personal 1040 due, and what extension option exists if she needs more time on the corporate return."], "studentDoes": ["State Priya's Form 1120-S filing deadline.", "State her K-1 delivery deadline.", "State her personal 1040 deadline.", "Identify the extension form available for her 1120-S (Form 7004) and confirm it does not extend any payment due."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "e4", "tag": "WIN Review", "title": "WIN Review: Setup & Deadlines", "eyebrow": "Module E · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Setup & Deadlines", "sub": "", "tag": "EXTENSION = MORE TIME ON PAPERWORK, NEVER ON PAYMENT"}, "script": ["Setup — EIN, registration, bookkeeping method — happens before the business takes its first dollar, not after. Every entity has its own form and its own deadline, and no matter which form, an extension only ever buys time to file — never time to pay."], "quiz": {"label": "Module E WIN Review — 5 questions", "questions": [{"q": "An EIN from the IRS is:", "opts": ["A paid service", "Free, from IRS.gov", "Only for corporations"], "answer": 1}, {"q": "An S-corp files:", "opts": ["Schedule C", "Form 1120-S", "Form 1065"], "answer": 1}, {"q": "K-1s from a partnership or S-corp are generally due:", "opts": ["April 15", "March 16", "December 31"], "answer": 1}, {"q": "Form 7004 provides:", "opts": ["More time to file only", "More time to file and to pay", "A waiver of all penalties"], "answer": 0}, {"q": "Bookkeeping method should be chosen:", "opts": ["At tax filing time", "Before the business's first invoice", "Only if the business has employees"], "answer": 1}]}}]}, {"group": "Track 2 · Module F — Self-Employment Tax & Payroll", "lessons": [{"id": "f1", "tag": "Teaching", "title": "SE Tax & Quarterly Estimates", "eyebrow": "Module F · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "SE Tax", "title": "Self-Employment Tax", "sub": "15.3% on 92.35% of net earnings", "tag": "SAFE HARBOR: 90% CURRENT YEAR / 100–110% PRIOR YEAR"}, "script": ["Self-employment tax replaces the employer/employee FICA split for a sole proprietor — 15.3% total. The calculation starts by multiplying net self-employment earnings by 92.35%, accounting for the fact that an employee's employer-paid half of FICA is never taxed as income.", "Because none of this gets withheld automatically, quarterly estimated payments are how it gets paid. The safe harbor rule protects against underpayment penalties: pay at least 90% of the current year's total tax liability, or 100% of last year's liability (110% if last year's income was high)."]}, {"id": "f2", "tag": "Teaching", "title": "Payroll, FICA/FUTA & Worker Classification", "eyebrow": "Module F · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Payroll vs. Contractor", "title": "FICA/FUTA & Worker Classification", "sub": "FICA 6.2% + 1.45%, employer matches both", "tag": "BEHAVIORAL • FINANCIAL • RELATIONSHIP"}, "script": ["Once Priya's S-corp pays her a salary, she's running payroll. FICA withholds 6.2% Social Security and 1.45% Medicare from the employee's wages, and the employer matches both. On top of that, FUTA is a federal unemployment tax paid by the employer alone.", "Getting the employee-versus-contractor call right matters because it's expensive to get wrong. The test looks at behavioral control, financial control, and the type of relationship. When it's genuinely unclear, a business can file Form SS-8 and ask the IRS to make the determination."]}, {"id": "f3", "tag": "Practice", "title": "Your Turn: Priya — Calculate the Quarterly Payment", "eyebrow": "Module F · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Priya Shah", "title": "Calculate the Quarterly Payment", "sub": "Sole-Prop-Era Net Earnings: $92,000", "tag": "SE TAX BASE → SE TAX OWED → ONE QUARTER'S ESTIMATE"}, "image": {"src": "assets/priya_docs.png", "alt": "Document Set — Priya Shah"}, "script": ["Before her S-corp election took effect, Priya's $92,000 in net self-employment earnings was fully exposed to SE tax. Walk the full calculation: apply the 92.35% adjustment to get her SE-tax base, calculate 15.3% self-employment tax on that base, then divide her total estimated annual liability by four to find one quarter's safe-harbor payment."], "studentDoes": ["Apply the 92.35% adjustment to Priya's $92,000 net earnings to find her SE-tax base.", "Calculate her total SE tax at 15.3% of that base.", "Confirm whether any portion of her earnings exceeds the Social Security wage base cap.", "Divide her estimated annual liability by four for one quarterly safe-harbor payment."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "f4", "tag": "Final", "title": "WIN Review: SE Tax & Payroll (Closes Track 2)", "eyebrow": "Module F · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review — Closes Track 2", "title": "SE Tax & Payroll", "sub": "", "tag": "SAFE HARBOR PROTECTS AGAINST UNDERPAYMENT PENALTIES"}, "script": ["Self-employment tax runs 15.3% against 92.35% of net earnings. Worker classification comes down to behavioral control, financial control, and the relationship itself. And the safe harbor rule — 90% of this year or 100 to 110% of last year — is what keeps a growing business out of underpayment penalty territory.", "That closes Track 2, Small Business Formation & Filing. Track 3 is next: Terrence Cole builds his books, and Angela Ruiz closes the course with a capstone that's deliberately messy."], "quiz": {"label": "Module F WIN Review — 5 questions", "questions": [{"q": "Self-employment tax is calculated on:", "opts": ["100% of net earnings", "92.35% of net earnings", "50% of net earnings"], "answer": 1}, {"q": "The Medicare portion of SE tax:", "opts": ["Is capped like Social Security", "Has no wage cap", "Doesn't apply to the self-employed"], "answer": 1}, {"q": "The worker-classification test looks at:", "opts": ["Pay rate and hours only", "Behavioral control, financial control, and relationship", "Age and experience"], "answer": 1}, {"q": "A business unsure how to classify a worker can file:", "opts": ["Form SS-8", "Form 941", "Form 940"], "answer": 0}, {"q": "The safe harbor rule for estimated payments requires paying at least:", "opts": ["50% of last year's tax", "90% of the current year's tax, or 100–110% of last year's", "Nothing, as long as it's paid by April 15"], "answer": 1}]}}]}, {"group": "Track 3 · Module G — Bookkeeping Fundamentals", "lessons": [{"id": "g1", "tag": "Teaching", "title": "Double-Entry Basics", "eyebrow": "Module G · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Track 3 · Module G", "title": "Double-Entry Basics", "sub": "Every transaction hits two accounts", "tag": "DEBITS = CREDITS, ALWAYS"}, "script": ["Welcome to Track 3. This track follows Terrence Cole, who runs a mobile pet-grooming business, and closes with Angela Ruiz's capstone.", "Double-entry bookkeeping means every transaction touches at least two accounts, and the two sides always balance. Watch four examples: a $2,400 laptop purchase — cash goes down, equipment (an asset) goes up. A grooming sale — cash goes up, revenue goes up. A business loan payment — cash goes down, and the loan liability goes down too. An owner draw — cash goes down, and owner's equity goes down."]}, {"id": "g2", "tag": "Teaching", "title": "Chart of Accounts & Cash vs. Accrual", "eyebrow": "Module G · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Chart of Accounts", "title": "Chart of Accounts", "sub": "Assets • Liabilities • Equity • Revenue • Expenses", "tag": "CASH vs. ACCRUAL — PICK ONE, STAY CONSISTENT"}, "script": ["A chart of accounts is the map every transaction gets sorted into, and it starts with five categories: assets, liabilities, equity, revenue, and expenses.", "Cash basis records a transaction when cash actually moves — simplest, and what the overwhelming majority of small businesses use. Accrual basis records income when it's earned and expenses when they're incurred, regardless of when cash changes hands — required once a business crosses a gross-receipts threshold in the tens of millions."]}, {"id": "g3", "tag": "Practice", "title": "Your Turn: Terrence — Build the Chart of Accounts", "eyebrow": "Module G · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Terrence Cole", "title": "Build the Chart of Accounts", "sub": "Mobile Pet-Grooming Business", "tag": "SORT EVERY TRANSACTION INTO ITS ACCOUNT"}, "image": {"src": "assets/terrence_docs.png", "alt": "Document Set — Terrence Cole"}, "script": ["Terrence hands you five transactions from his first month in business: an equipment purchase for his grooming van, grooming income from clients, a payment on the loan he took out to buy the van, a supply purchase, and a draw he took for personal expenses.", "Sort each transaction into the correct account category, and identify both sides of the double entry for each one."], "studentDoes": ["Sort the equipment purchase into its account category (asset) and identify both sides of the entry.", "Sort the grooming income into its account category (revenue) and identify both sides.", "Sort the loan payment into its account category (liability reduction) and identify both sides.", "Sort the supply purchase into its account category (expense) and identify both sides.", "Sort the owner draw into its account category (equity reduction) and identify both sides."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "g4", "tag": "WIN Review", "title": "WIN Review: Bookkeeping Fundamentals", "eyebrow": "Module G · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Bookkeeping Fundamentals", "sub": "", "tag": "MOST SMALL BUSINESSES USE CASH BASIS"}, "script": ["Double-entry bookkeeping means every transaction touches two accounts, and debits always equal credits. A chart of accounts sorts everything into five categories. And most small businesses use cash basis, unless their size requires accrual instead."], "quiz": {"label": "Module G WIN Review — 5 questions", "questions": [{"q": "In double-entry bookkeeping, every transaction affects:", "opts": ["One account", "At least two accounts", "All accounts equally"], "answer": 1}, {"q": "An owner draw reduces:", "opts": ["Revenue", "Owner's equity", "Liabilities"], "answer": 1}, {"q": "The five account categories are:", "opts": ["Cash, credit, debit, loan, equity", "Assets, liabilities, equity, revenue, expenses", "Income, outcome, profit, loss, tax"], "answer": 1}, {"q": "Cash basis bookkeeping records a transaction:", "opts": ["When it is earned or incurred", "When cash actually moves", "At year end only"], "answer": 1}, {"q": "Paying down a business loan:", "opts": ["Increases the liability", "Decreases the liability", "Has no effect on the liability"], "answer": 1}]}}]}, {"group": "Track 3 · Module H — Recordkeeping & Retention", "lessons": [{"id": "h1", "tag": "Teaching", "title": "What to Keep", "eyebrow": "Module H · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Recordkeeping", "title": "What to Keep", "sub": "Income • Expense • Asset • Credit/Deduction Support", "tag": "NEVER MIX PERSONAL AND BUSINESS ACCOUNTS"}, "script": ["Good bookkeeping only matters if the records behind it survive. Four categories cover almost everything: income records, expense records, asset records, and records supporting any credit or deduction claimed.", "And one habit sits underneath all four categories: never mix personal and business accounts. A single business checking account and a single business card make every one of these four categories dramatically easier to prove."]}, {"id": "h2", "tag": "Teaching", "title": "How Long to Keep It", "eyebrow": "Module H · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Retention Periods", "title": "How Long to Keep It", "sub": "3 years standard • 6 years underreported income • 7 years bad debt", "tag": "4 YEARS EMPLOYMENT TAX • INDEFINITE IF NO RETURN OR FRAUD"}, "script": ["Three years is the standard rule, matching the general audit window. Six years applies if income was underreported by 25% or more. Seven years applies specifically to a bad debt deduction or a loss from worthless securities. Four years applies to employment tax records. And if no return was filed at all, or if fraud is involved, there's no time limit — keep those records indefinitely."]}, {"id": "h3", "tag": "Practice", "title": "Your Turn: Terrence — Organize the Records", "eyebrow": "Module H · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Terrence Cole", "title": "Organize the Records", "sub": "3 Years of Receipts · One Depreciation Schedule · Last Year's Return", "tag": "SORT BY RETENTION CLOCK. FLAG WHAT'S MISSING."}, "image": {"src": "assets/terrence_docs.png", "alt": "Document Set — Terrence Cole"}, "script": ["Terrence hands you a box: three years of receipts, one depreciation schedule for his grooming van, and a copy of last year's filed return. Sort each item by its retention rule.", "Then flag what's genuinely missing from his recordkeeping, not just what's disorganized: Terrence still doesn't have a dedicated business bank account. Note that gap explicitly — it's a system-level issue, not a filing problem."], "studentDoes": ["Assign the correct retention period to the receipts.", "Assign the correct retention period to the depreciation schedule.", "Assign the correct retention period to last year's filed return.", "Identify the missing system-level item (a dedicated business bank account) and explain why it matters."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "h4", "tag": "WIN Review", "title": "WIN Review: Recordkeeping & Retention", "eyebrow": "Module H · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Recordkeeping & Retention", "sub": "", "tag": "A DEDICATED BUSINESS ACCOUNT FIXES MOST GAPS"}, "script": ["Four categories of records to keep: income, expense, asset, and anything supporting a credit or deduction. Three years is the standard retention clock, stretching further for specific situations. And one dedicated business account, kept completely separate from personal finances, prevents the most recordkeeping headaches."], "quiz": {"label": "Module H WIN Review — 5 questions", "questions": [{"q": "The standard record retention period is:", "opts": ["1 year", "3 years", "10 years"], "answer": 1}, {"q": "If income was underreported by 25% or more, retention extends to:", "opts": ["4 years", "6 years", "7 years"], "answer": 1}, {"q": "If no return was filed at all, records should be kept:", "opts": ["3 years", "7 years", "Indefinitely"], "answer": 2}, {"q": "The single habit that makes recordkeeping dramatically easier is:", "opts": ["A bigger filing cabinet", "A dedicated business bank account", "A yearly cleanout"], "answer": 1}, {"q": "Employment tax records should generally be kept for:", "opts": ["2 years", "4 years", "10 years"], "answer": 1}]}}]}, {"group": "Track 3 · Module I — Deductions, Depreciation & Home Office", "lessons": [{"id": "i1", "tag": "Teaching", "title": "Ordinary & Necessary + Substantiation", "eyebrow": "Module I · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "The §162 Test", "title": "Ordinary & Necessary + Substantiation", "sub": "Ordinary and necessary", "tag": "SUBSTANTIATE: AMOUNT • DATE • PLACE • PURPOSE"}, "script": ["Every business deduction has to clear one lens first: is it ordinary and necessary. That's the default filter for anything a business owner wants to write off.", "But passing that test isn't the end of the job — it also has to be substantiated: the amount, the date, the business place or purpose, all documented at the time or close to it. Meals are only 50% deductible, and need the business purpose noted. And anything used for both personal and business purposes has to be prorated to the actual business-use percentage, never assumed at 100%."]}, {"id": "i2", "tag": "Teaching", "title": "Depreciation, Section 179 & Home Office", "eyebrow": "Module I · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Depreciation & Home Office", "title": "Section 179 & Home Office", "sub": "MACRS • Section 179 • Bonus Depreciation", "tag": "HOME OFFICE: REGULAR USE + EXCLUSIVE USE"}, "script": ["A major equipment purchase usually isn't fully deducted in the year of purchase — MACRS depreciation spreads that cost over the asset's useful life. Section 179 and bonus depreciation can accelerate that.", "The home office deduction has two tests that both must be met: regular use — used consistently — and exclusive use — used ONLY for business, no personal use at all, ever. Meet both, and there are two ways to calculate it: the simplified method, a flat $5 per square foot up to 300 square feet, or the actual-expense method on Form 8829."]}, {"id": "i3", "tag": "Practice", "title": "Your Turn: Terrence — Sort the Deductions", "eyebrow": "Module I · Lesson 3", "flow": ["VIDEO", "PRACTICE", "NEXT"], "slide": {"eyebrow": "Your Turn — Terrence Cole", "title": "Sort the Deductions", "sub": "Van Conversion: $6,200 · Home Office: 180 sq ft · Family Cell Phone: No Log", "tag": "DEDUCTIBLE? NEEDS PRORATION? UNSUPPORTED?"}, "image": {"src": "assets/terrence_docs.png", "alt": "Document Set — Terrence Cole"}, "script": ["Terrence brings you three items to sort. First, a $6,200 grooming-van conversion — fully business use, and a strong Section 179 candidate. Second, a 180-square-foot room he uses only for scheduling, invoicing, and storing grooming supplies — check both the regular-use and exclusive-use tests. Third, his family's shared cell phone bill, which he wants to deduct a portion of, but he has no log showing what percentage is business use.", "Sort all three: deductible as claimed, needs proration, or unsupported as presented. Without a business-use log, you cannot invent a percentage."], "studentDoes": ["Confirm the van conversion qualifies as a Section 179 candidate and note why.", "Apply the regular-use and exclusive-use tests to the 180 sq ft home office and state whether it qualifies.", "Evaluate the cell phone bill and state why it cannot be deducted as presented.", "Write what documentation Terrence would need to bring before the cell phone deduction could be claimed."], "note": "Practice — graded as completion, no formal quiz"}, {"id": "i4", "tag": "WIN Review", "title": "WIN Review: Deductions, Depreciation & Home Office", "eyebrow": "Module I · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review", "title": "Deductions, Depreciation & Home Office", "sub": "", "tag": "NO LOG, NO PERCENTAGE — DON'T INVENT ONE"}, "script": ["Every deduction has to be ordinary, necessary, and substantiated. The home office deduction requires both regular use and exclusive use — fail either test and it doesn't qualify. And when documentation for a mixed-use expense doesn't exist, the answer is never to estimate a percentage."], "quiz": {"label": "Module I WIN Review — 5 questions", "questions": [{"q": "A business deduction must be:", "opts": ["Convenient", "Ordinary and necessary", "Pre-approved"], "answer": 1}, {"q": "Substantiation requires documenting:", "opts": ["Amount only", "Amount, date, place, and purpose", "Just a receipt"], "answer": 1}, {"q": "Meals are generally deductible at:", "opts": ["100%", "50%", "0%"], "answer": 1}, {"q": "The home office deduction requires:", "opts": ["Regular use only", "Exclusive use only", "Both regular AND exclusive use"], "answer": 2}, {"q": "Without a business-use log for a mixed-use expense, a preparer should:", "opts": ["Estimate a reasonable percentage", "Not claim a percentage until documentation exists", "Claim 100% to be safe"], "answer": 1}]}}]}, {"group": "Track 3 · Module J — Deadlines, Penalties & Staying Off the Radar", "lessons": [{"id": "j1", "tag": "Teaching", "title": "The Compliance Calendar", "eyebrow": "Module J · Lesson 1", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Compliance Calendar", "title": "The Full Compliance Calendar", "sub": "Every deadline from this course, one page", "tag": "QUARTERLY ESTIMATES • 941/940 • ENTITY RETURNS • PERSONAL RETURN"}, "script": ["This lesson pulls together every deadline taught across all three tracks into one calendar. Quarterly estimated payments in mid-April, mid-June, mid-September, and mid-January. Form 941 filed quarterly for any business running payroll. Form 940 filed annually for federal unemployment. Partnership and S-corp returns in mid-March. Personal returns in mid-April."]}, {"id": "j2", "tag": "Teaching", "title": "Penalties, Interest & the State/Local Layer", "eyebrow": "Module J · Lesson 2", "flow": ["VIDEO", "NEXT"], "slide": {"eyebrow": "Penalties & Interest", "title": "Penalties, Interest & the State Layer", "sub": "Failure-to-file: 5%/month • Failure-to-pay: 0.5%/month", "tag": "FEDERAL RETURN, PLUS STATE ADJUSTMENTS"}, "script": ["Failure-to-file runs 5% of unpaid tax per month. Failure-to-pay runs a much smaller 0.5% per month. When both apply in the same month, the combined rate lands around 4.5% — but interest keeps accruing on top of both, and interest is never waived.", "The single most valuable habit from this whole lesson: file on time even if the money to pay isn't there yet. One more layer sits on top of everything: nexus — a business's obligation to collect and pay tax in a state — can be triggered by physical presence or by economic activity alone."]}, {"id": "j3", "tag": "Capstone", "title": "Your Turn: Angela Capstone", "eyebrow": "Module J · Lesson 3", "flow": ["VIDEO", "CAPSTONE", "NEXT"], "slide": {"eyebrow": "Capstone — Angela Ruiz", "title": "Angela Capstone", "sub": "Single-Member LLC, Bookkeeping Services · Year 2 · Gross Receipts: $61,000", "tag": "SEPARATE WHAT'S SUPPORTED. FLAG WHAT ISN'T. FINALIZE NOTHING UNSUPPORTED."}, "image": {"src": "assets/angela_docs.png", "alt": "Capstone Document Set — Angela Ruiz"}, "script": ["Angela Ruiz runs a bookkeeping-services business, now in its second year, with $61,000 in gross receipts. Her file has more than one issue stacked into it — on purpose, so this functions as a real capstone.", "First: she bought $1,800 in equipment on her personal credit card, mixed in with personal purchases — the business expense is real, but it needs to be correctly reclassified. Second: she claims a 220-square-foot home office, but her home gym also uses part of that same room — that fails the exclusive-use test. Third: her last three years of returns show losses every year — that pattern raises hobby-loss questions the IRS specifically looks for. Fourth: a payment app shows a $4,300 deposit that doesn't appear reconciled against any 1099-K or invoice on file.", "Your job across all four issues is the same: separate what's supported from what isn't, identify precisely what additional information is needed, and do not finalize any unsupported treatment by guessing."], "studentDoes": ["Determine the correct treatment for the $1,800 equipment purchase made on a personal card.", "Apply the exclusive-use test to the 220 sq ft home office claim and state whether it qualifies.", "Identify why three consecutive loss years raises a hobby-loss concern and what additional facts would need to be gathered.", "Identify what's needed to resolve the unreconciled $4,300 deposit.", "Write a summary memo separating supported / needs correction / unsupported for all four issues, with the specific follow-up question for each."], "note": "Capstone — graded as completion, no formal quiz"}, {"id": "j4", "tag": "Final", "title": "WIN Review + Final Assessment", "eyebrow": "Module J · Lesson 4", "flow": ["VIDEO", "QUIZ", "NEXT"], "slide": {"eyebrow": "WIN Review — Final Assessment", "title": "Closes All Three Tracks", "sub": "", "tag": "LOOK → ENTER → COMPARE, EVERY TIME, ON EVERY FILE"}, "script": ["You've now worked through three tracks and four clients: Marcus, whose bracket and credit questions taught the fundamentals of individual tax; Priya, whose entity choice taught how business structure drives tax exposure; Terrence, whose books and deductions taught bookkeeping and substantiation; and Angela, whose capstone brought every one of those skills together in a single, deliberately messy file.", "The habit underneath all of it hasn't changed since Start Here: LOOK at the document, ENTER what it actually says, COMPARE it against what you expect — and when something doesn't add up or isn't fully documented, stop and ask rather than filling the gap yourself. That's the whole job."], "quiz": {"label": "Final Assessment — 6 questions, across all three tracks", "questions": [{"q": "A taxpayer's effective tax rate is always:", "opts": ["Higher than their marginal bracket", "Lower than their marginal bracket", "Equal to their marginal bracket"], "answer": 1}, {"q": "A sole proprietor's SE tax is calculated on:", "opts": ["100% of net earnings", "92.35% of net earnings", "50% of net earnings"], "answer": 1}, {"q": "In an S-corp, only the ______ portion is subject to payroll tax:", "opts": ["Distribution", "Salary", "Total profit"], "answer": 1}, {"q": "The home office deduction requires:", "opts": ["Regular use only", "Regular AND exclusive use", "Any home workspace at all"], "answer": 1}, {"q": "Standard record retention is 3 years, extending to 6 years when:", "opts": ["A home office is claimed", "Income was underreported by 25% or more", "The business uses accrual accounting"], "answer": 1}, {"q": "When documentation for an item is incomplete, the correct step is to:", "opts": ["Estimate a reasonable figure", "Ask for the missing documentation before finalizing", "Leave it off without asking"], "answer": 1}]}}, {"id": "fin", "tag": "Complete", "title": "Final Completion Area", "eyebrow": "Course Complete", "flow": ["CERTIFICATE"], "slide": {"eyebrow": "Final Completion Area", "title": "Course Complete", "sub": "Final assessment result · Angela capstone confirmation · WIN Certificate of Completion · Optional WIN Tax Lab", "tag": "SKILLS ARE WEALTH."}, "script": ["This is skills training. It does not by itself provide an IRS credential, PTIN, professional license, job, or authorization to prepare paid returns."]}]}]};
